 for(let i=0;i<a.length;i+=4){const v=Math.max(a[i],a[i+1],a[i+2]),m=Math.min(a[i],a[i+1],a[i+2]),sat=(v-m)/Math.max(v,0.255);for(let j=0;j<3;j++){const themed=v*(1-sat)+(s.color[j]/255)*v*sat;a[i+j]=a[i+j]*.12+themed*.88;}}
