for(const s of data.species){const option=document.createElement('option');option.value=String(s.level);option.textContent=`Nivel ${s.level} · ${s.name}`;picker.append(option);}
function update(){const level=Number(picker.value),s=data.species[level-1];description.textContent=`Nivel ${s.level} · ${s.name} · ${s.type} · #${String(s.dex).padStart(3,'0')}`;render(primary,s).catch(()=>{description.textContent='No se pudo cargar la vista previa.';});}
